import { test } from 'node:test';
import assert from 'node:assert/strict';
import { escopoDeBloco, tdzEmAcao, hoistingDeVar } from './solution.mjs';

test('variável de bloco não vaza para fora do bloco', () => {
  const resultado = escopoDeBloco();
  assert.equal(resultado.visivel, 'alterada-dentro');
  assert.equal(resultado.escondidaVisivelAqui, false);
});

test('let usada antes da declaração cai na zona morta temporal', () => {
  assert.equal(tdzEmAcao(), 'reference-error');
});

test('var é içada com undefined (hoisting)', () => {
  const resultado = hoistingDeVar();
  assert.equal(resultado.antes, 'undefined');
  assert.equal(resultado.depois, 'oi');
});

