export function escopoDeBloco() {
  let visivel = 'fora';
  if (true) {
    let escondida = 'dentro';
    visivel = 'alterada-dentro';
  }
  const escondidaVisivelAqui = typeof escondida !== 'undefined';
  return { visivel, escondidaVisivelAqui };
}

export function tdzEmAcao() {
  let resultado;
  try {
    resultado = antes; // antes da declaração: zona morta temporal
  } catch {
    return 'reference-error';
  }
  let antes = 1;
  return 'ok';
}

export function hoistingDeVar() {
  const antes = typeof mensagem; // var içada: aqui vale undefined
  var mensagem = 'oi';
  return { antes, depois: mensagem };
}
